# ---------- Keccak ----------
def _rot(x, n):
    n = n % 64
    return ((x >> (64 - n)) | (x << n)) & 0xFFFFFFFFFFFFFFFF if n != 0 else x & 0xFFFFFFFFFFFFFFFF
_keccak_RC = [0x0000000000000001,0x0000000000008082,0x800000000000808a,0x8000000080008000,0x000000000000808b,0x0000000080000001,0x8000000080008081,0x8000000000008009,0x000000000000008a,0x0000000000000088,0x0000000080008009,0x000000008000000a,0x000000008000808b,0x800000000000008b,0x8000000000008089,0x8000000000008003,0x8000000000008002,0x8000000000000080,0x000000000000800a,0x800000008000000a,0x8000000080008081,0x8000000000008080,0x0000000080000001,0x8000000080008008]
_keccak_rot = [[0,36,3,41,18],[1,44,10,45,2],[62,6,43,15,61],[28,55,25,21,56],[27,20,39,8,14]]
def _keccak_f1600(s):
    for rnd in range(24):
        C = [s[x] ^ s[x+5] ^ s[x+10] ^ s[x+15] ^ s[x+20] for x in range(5)]
        D = [C[(x+4)%5] ^ _rot(C[(x+1)%5],1) for x in range(5)]
        for x in range(5):
            for y in range(5):
                s[x+5*y] ^= D[x]
        B=[0]*25
        for x in range(5):
            for y in range(5):
                B[y+5*((2*x+3*y)%5)]=_rot(s[x+5*y],_keccak_rot[x][y])
        for x in range(5):
            for y in range(5):
                s[x+5*y]=B[x+5*y] ^ ((~B[(x+1)%5+5*y]) & B[(x+2)%5+5*y])
                s[x+5*y]&=0xFFFFFFFFFFFFFFFF
        s[0]^=_keccak_RC[rnd]
    return s
def keccak_256(data: bytes) -> bytes:
    rate=136; suffix=0x01; s=[0]*25
    msg=bytearray(data); msg.append(suffix)
    while len(msg)%rate!=0: msg.append(0x00)
    msg[-1]|=0x80
    for off in range(0,len(msg),rate):
        block=msg[off:off+rate]
        for i in range(rate//8):
            v=block[i*8]|(block[i*8+1]<<8)|(block[i*8+2]<<16)|(block[i*8+3]<<24)|(block[i*8+4]<<32)|(block[i*8+5]<<40)|(block[i*8+6]<<48)|(block[i*8+7]<<56)
            s[i]^=v
        s=_keccak_f1600(s)
    out=bytearray()
    for i in range(4):
        v=s[i]
        out.extend([v&0xFF,(v>>8)&0xFF,(v>>16)&0xFF,(v>>24)&0xFF,(v>>32)&0xFF,(v>>40)&0xFF,(v>>48)&0xFF,(v>>56)&0xFF])
    return bytes(out)
def selector(sig: str) -> str:
    return keccak_256(sig.encode()).hex()[:8]

# ---------- Levenshtein for tips ----------
def levenshtein(a,b):
    if a==b: return 0
    la=len(a); lb=len(b)
    if la==0: return lb
    if lb==0: return la
    prev=list(range(lb+1))
    for i in range(1,la+1):
        cur=[i]+[0]*lb
        for j in range(1,lb+1):
            cost=0 if a[i-1]==b[j-1] else 1
            cur[j]=min(prev[j]+1,cur[j-1]+1,prev[j-1]+cost)
        prev=cur
    return prev[lb]

def find_similar(inp, candidates):
    best=None; bestd=None
    for c in candidates:
        d=levenshtein(inp,c)
        if bestd is None or d<bestd:
            bestd=d; best=c
    # threshold: clap uses something like distance small; use <=3 and also jaro-like? simple: if bestd<=3 and bestd < len(inp) maybe?
    # Observed: Prague->prague (d=1) tip, prauge->prague (d=2) tip, foo->? (d large) no tip, ABI->abi (d=3) no tip, ' hashes'->hashes (d=1) tip
    # So threshold maybe 2? But ABI d=3 no tip, so threshold 2 fits. Check ' hashes' d=1 tip yes.
    # Use threshold: d<=2 or (d==3 and len>5?) Let's use d<=2
    if bestd is not None and bestd<=2:
        return best
    # also handle case-insensitive? Prague vs prague d=1 already tip. Good.
    return None

